import 'dart:io';

import 'package:runfiles/runfiles.dart';

/// Reads a transitive pub spoke's `pubspec.yaml` from runfiles.
///
/// The spokes are generated by `pub.from_lock()` and `pub.package()` in this
/// workspace's `MODULE.bazel`. The file is not a compile input and not a
/// `lib/` resource; it reaches this test only through the generated
/// `dart_library`'s `data`, which is what this fixture exists to prove.
void readPubspec(Runfiles runfiles, String path, String name) {
  final found = runfiles.rlocation(path);
  final pubspec = File(found);
  if (!pubspec.existsSync()) {
    stderr.writeln('The pub spoke pubspec.yaml is not in runfiles: $found');
    exit(1);
  }
  final content = pubspec.readAsStringSync();
  if (!content.contains('name: $name')) {
    stderr.writeln('Unexpected pubspec content at $found:\n$content');
    exit(1);
  }
}

void main() {
  final runfiles = Runfiles.create();

  // A hosted lock spoke.
  readPubspec(
    runfiles,
    'ai_rules_dart++pub+dart_pub__collection/pubspec.yaml',
    'collection',
  );

  // An explicit `pub.package()`, reached transitively through `file`'s
  // dependency on `path`.
  readPubspec(runfiles, 'path/pubspec.yaml', 'path');
}
